import numpy as np
from scipy import stats
from sklearn.feature_selection import f_classif

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on effect size and significance
    drivers = []

    # Check for strong associations with outcome
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('clinical', 'cohort'):
            # For clinical/cohort variables, check if they're strongly associated with outcome
            if feats.x.shape[1] > i:  # Ensure index is valid
                t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
                if abs(t_stat) > 3.0 and p_val < 0.001:
                    drivers.append(fid)

    # If we have a driver, adjust for it
    if drivers:
        # Remove correlated features to avoid redundancy
        keep = set()
        for i, fid in enumerate(feats.ids):
            if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
                continue
            # Check correlation with drivers
            is_correlated = False
            for driver in drivers:
                if driver in feats.ids:
                    driver_idx = feats.column(driver)
                    if feats.x.shape[1] > driver_idx and feats.x.shape[1] > i:
                        corr = np.corrcoef(feats.x[:, i], feats.x[:, driver_idx])[0, 1]
                        if abs(corr) > 0.6:
                            is_correlated = True
                            break
            if not is_correlated:
                keep.add(fid)

        # Use remaining features for modeling
        columns = tuple(keep)
    else:
        # No clear driver, use all features
        columns = feats.ids

    # Find top features by association with outcome
    if len(columns) > 0:
        # Calculate F-scores for all features
        col_indices = []
        for fid in columns:
            try:
                col_indices.append(feats.column(fid))
            except:
                continue

        if len(col_indices) > 0 and len(feats.x) > 0:
            try:
                f_scores, _ = f_classif(feats.x[:, col_indices], feats.y)

                # Sort by F-score and take top 3
                sorted_indices = np.argsort(f_scores)[::-1][:3]
                top_features = [columns[i] for i in sorted_indices if i < len(columns)]

                # If we have a strong signal, consider interaction terms
                products = []
                if len(top_features) >= 2:
                    # Look for interactions between top features
                    for i in range(min(len(top_features), 2)):
                        for j in range(i+1, min(len(top_features), 2)):
                            products.append((top_features[i], top_features[j]))

                # Create weighted score using top features
                loadings = {}
                for i, fid in enumerate(top_features):
                    if i < len(f_scores):
                        loadings[fid] = f_scores[i]

                return Design(
                    drivers=tuple(drivers),
                    columns=columns,
                    products=tuple(products),
                    loadings=loadings
                )
            except:
                pass

    return Design(
        drivers=tuple(drivers),
        columns=(),
        products=(),
        loadings={}
    )
